import React, { useCallback, useEffect, useState } from 'react';
import { useForm } from '@teambit/base-react.forms.form';
import { InputText } from './input-text';
import type { InputTextProps } from './input-text';

export type RequiredInputTextProps = {
  customErrorMessage?: string;
} & InputTextProps;

function useRequired(name: string) {
  const [message, setMessage] = useState<string | undefined | null>(undefined);
  const { onValidate, values } = useForm();
  const value = values?.[name];

  useEffect(() => {
    if (!value || value === '') return;
    setMessage(undefined);
  }, [value]);

  useEffect(() => {
    onValidate?.(name, message);
  }, [name, message, onValidate]);

  const handleBlur = useCallback((e) => {
    if (e.target.required && (!e.target.value || e.target.value === '')) {
      return setMessage('Required');
    }
    return undefined;
  }, []);

  return { errorMessage: message, onBlur: handleBlur };
}

export function RequiredInputText({
  name = 'required',
  placeholder = 'Required',
  customErrorMessage,
  ...rest
}: RequiredInputTextProps) {
  const { errorMessage, onBlur } = useRequired(name);
  const error = errorMessage || customErrorMessage;

  return (
    <InputText
      {...rest}
      name={name}
      placeholder={placeholder}
      error={!!error}
      message={error}
      onBlur={onBlur}
      required
    />
  );
}

